CREATE TABLE app_users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(40) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE songs (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(180) NOT NULL, description TEXT NULL, bpm INT NOT NULL, duration_seconds INT NOT NULL, procession BOOLEAN NOT NULL DEFAULT FALSE, exhibition BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE song_tracks (id BIGINT PRIMARY KEY AUTO_INCREMENT, song_id BIGINT NOT NULL, track_type VARCHAR(30) NOT NULL, original_filename VARCHAR(255) NOT NULL, media_path VARCHAR(500) NOT NULL, media_status VARCHAR(30) NOT NULL DEFAULT 'UPLOADED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_song_tracks_song FOREIGN KEY (song_id) REFERENCES songs(id) ON DELETE CASCADE, CONSTRAINT uk_song_track_type UNIQUE(song_id, track_type));
CREATE TABLE song_sections (id BIGINT PRIMARY KEY AUTO_INCREMENT, song_id BIGINT NOT NULL, title VARCHAR(180) NOT NULL, note TEXT NULL, start_seconds INT NOT NULL, end_seconds INT NOT NULL, color VARCHAR(20) NOT NULL, question BOOLEAN NOT NULL DEFAULT FALSE, answer BOOLEAN NOT NULL DEFAULT FALSE, sort_order INT NOT NULL, CONSTRAINT fk_song_sections_song FOREIGN KEY (song_id) REFERENCES songs(id) ON DELETE CASCADE);
CREATE TABLE song_section_tracks (section_id BIGINT NOT NULL, track_type VARCHAR(30) NOT NULL, PRIMARY KEY(section_id, track_type), CONSTRAINT fk_section_tracks_section FOREIGN KEY (section_id) REFERENCES song_sections(id) ON DELETE CASCADE);
